"""Sequential batch-job runner preserving Meridian CRM 4.2 error semantics."""

from typing import Callable


def run_jobs(jobs: list[dict], executor: Callable[[dict], object]) -> list[dict]:
    """Run jobs sequentially and return one log entry per attempted job."""
    run_log: list[dict] = []

    for job in jobs:
        policy = job["on_error"]["policy"]
        max_attempts = (
            job["on_error"]["retries"] + 1 if policy == "RETRY" else 1
        )
        attempts = 0
        succeeded = False

        for _ in range(max_attempts):
            attempts += 1
            try:
                executor(job)
            except Exception:
                continue
            succeeded = True
            break

        if succeeded:
            run_log.append(
                {
                    "name": job["name"],
                    "attempts": attempts,
                    "outcome": "ok",
                    "audits": [],
                }
            )
            continue

        if policy == "CONTINUE":
            run_log.append(
                {
                    "name": job["name"],
                    "attempts": attempts,
                    "outcome": "skip",
                    "audits": ["BATCH_ROWSKIP"],
                }
            )
            continue

        run_log.append(
            {
                "name": job["name"],
                "attempts": attempts,
                "outcome": "abort",
                "audits": [],
            }
        )
        break

    return run_log
